mapper.update:
UPDATE `group`
SET lifecycle = #{lifecycle}
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}

UPDATE `group`
SET in_service = #{inService}
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}

UPDATE `group`
SET lifecycle = 'PAUSED',
    paused_at = #{pausedAt}
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}

UPDATE `group`
SET lifecycle                 = 'ACTIVE',
    paused_accumulated_millis = paused_accumulated_millis + #{addMillis},
    paused_at                 = NULL
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
